mapper.select:
select
con.Con_Name as conName, mn.Cpa_Id as cpaId, con.Con_Id as conId, con.Con_Party_A_Id as conPartyAId, c1.C_Name as conPartyAName, mn.Cpa_Type as cpaType, mn.Cpa_Sources as cpaSources, mn.Cpa_Apply_Date as cpaApplyDate, mn.Cpa_Apply_Uid as cpaApplyUid, u.U_Name as cpaApplyUname, mn.Cpa_Approved_Amount as cpaApprovedAmount, (select sum(cpaf.Cpaf_Application) from Con_Pay_Apply_Flow cpaf where cpaf.Cpa_Id=mn.Cpa_Id and cpaf.State=7 and cpaf.State!=3 ) as cpaPaymentAmount, mn.Cpa_Payment_Proportion as cpaPaymentProportion, mn.Cpa_Remarks as cpaRemarks, mn.Cpa_Create_Time as cpaCreateTime, mn.Cpa_Foreign as cpaForeign, mn.P_Id as pId, u.U_Name as uName from Con_Pay_Apply mn
left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_User u on mn.Cpa_Apply_Uid=u.U_ID left join SYS_Company c1 on con.Con_Party_A_Id=c1.C_Id
and mn.Te_Id = #{params.teId}
and mn.P_Id = #{params.pId}
and mn.Con_Id = #{params.conId}
and con.Con_Name like concat('%',#{params.conName},'%')
and mn.Cpa_Sources = #{params.cpaSources}
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Cpa_Create_Time desc
limit #{params.start},#{params.size}

select
count(*)
from Con_Pay_Apply mn

left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_User u on mn.Cpa_Apply_Uid=u.U_ID
left join SYS_Company c1 on con.Con_Party_A_Id=c1.C_Id

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.P_Id = #{params.pId}
    
    
        and mn.Con_Id = #{params.conId}
    
    
        and con.Con_Name like concat('%',#{params.conName},'%')
    
    
        and mn.Cpa_Sources = #{params.cpaSources}
    
    
        
            
                and likePname(#{params.pName},pro.P_Id)=true
            
            
                and INSTR(pro.P_Name,#{params.pName})
